#include "tracker.h"
#include <curl/curl.h>
typedef struct{unsigned char*d;size_t n,c;}Buf;static size_t wr(void*p,size_t s,size_t n,void*u){Buf*b=u;size_t z=s*n;if(b->n+z>b->c){b->c=b->c?b->c*2:4096;while(b->c<b->n+z)b->c*=2;b->d=realloc(b->d,b->c);}memcpy(b->d+b->n,p,z);b->n+=z;return z;}
size_t tracker_get_peers(const Torrent*t,const unsigned char id[20],PeerAddress*out,size_t max){size_t count=0;for(size_t i=0;i<t->tracker_count&&count<max;i++){if(strncmp(t->trackers[i],"http",4))continue;CURL*c=curl_easy_init();if(!c)continue;char*ih=curl_easy_escape(c,(const char*)t->info_hash,20);char*pid=curl_easy_escape(c,(const char*)id,20);char url[4096];snprintf(url,sizeof url,"%s%sinfo_hash=%s&peer_id=%s&port=%d&uploaded=0&downloaded=0&left=%llu&compact=1",t->trackers[i],strchr(t->trackers[i],'?')?"&":"?",ih,pid,BT_PORT,(unsigned long long)t->total_length);Buf b={0};curl_easy_setopt(c,CURLOPT_URL,url);curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,wr);curl_easy_setopt(c,CURLOPT_WRITEDATA,&b);curl_easy_setopt(c,CURLOPT_TIMEOUT,15L);if(curl_easy_perform(c)==CURLE_OK){size_t used;BValue*v=bdecode(b.d,b.n,&used),*p=v?bdict_get(v,"peers"):NULL;if(p&&p->type==B_BYTES)for(size_t j=0;j+6<=p->bytes.length&&count<max;j+=6){struct in_addr a;memcpy(&a.s_addr,p->bytes.data+j,4);inet_ntop(AF_INET,&a,out[count].ip,sizeof out[count].ip);out[count].port=(uint16_t)((p->bytes.data[j+4]<<8)|p->bytes.data[j+5]);count++;}bfree(v);}free(b.d);curl_free(ih);curl_free(pid);curl_easy_cleanup(c);}return count;}
